const fs = require('node:fs')
const path = require('node:path')
const {
  assetRoot,
  auditRoot,
  buildRuntimeManifest,
  loadSources
} = require('./contract-lib.cjs')

function renderExitMatrix(matrix) {
  const dispositionCounts = matrix.rows.reduce((counts, row) => {
    counts[row.disposition] = (counts[row.disposition] || 0) + 1
    return counts
  }, {})
  const lines = [
    '# Codex runtime exit-authority matrix',
    '',
    '> Generated from `2026-08-06-codex-runtime-exit-authority-matrix.json`. Do not edit this file by hand.',
    '',
    `Candidate authority: ${matrix.candidateAuthority}`,
    '',
    `Disposition totals: ${Object.entries(dispositionCounts).map(([key, value]) => `${key}=${value}`).join(', ')}.`,
    '',
    '| Exit | Trigger | Decision owner | Disposition | Ready result | Candidate | Publication | Gate |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |'
  ]
  for (const row of matrix.rows) {
    lines.push(
      `| \`${row.id}\` | ${row.trigger} | ${row.targetDecisionPoint} | ${row.disposition} | ${row.readyOutcome} / ${row.terminalReason} | ${row.candidatePolicy} | ${row.publicationPolicy} | ${row.behaviorGate} |`
    )
  }
  lines.push('', '## Current terminal-reason coverage', '')
  for (const [reason, ids] of Object.entries(matrix.terminalReasonCoverage)) {
    lines.push(`- \`${reason}\` -> ${ids.map((id) => `\`${id}\``).join(', ')}`)
  }
  lines.push(
    '',
    '## Locked closeout rule',
    '',
    'Codex terminal and item events can only form a candidate. A Ready-owned closeout is the sole product terminal writer and canonical assistant-message writer. Rejected native bodies are never rewritten; any unproven history parity retires that thread as `publication_diverged`.',
    ''
  )
  return lines.join('\n')
}

function main() {
  const { exitMatrix } = loadSources()
  const manifest = buildRuntimeManifest()
  fs.writeFileSync(
    path.join(assetRoot, 'runtime-manifest.json'),
    `${JSON.stringify(manifest, null, 2)}\n`
  )
  fs.writeFileSync(
    path.join(auditRoot, '2026-08-06-codex-runtime-exit-authority-matrix.md'),
    renderExitMatrix(exitMatrix)
  )
  console.log('Generated Codex E0 manifest and exit-authority audit.')
}

main()
